  assign SpectrumDelay_out1 = (FFT_N_out2_1 == 1'b1 ? SpectrumDelay_reg :
              SpectrumDelay_bypass_delay);

  assign SpectrumGate_out1 = (sumGate_1 == 1'b0 ? SpectrumZero_out1 :
              SpectrumDelay_out1);

  assign SpectrumSum_add_cast = {12'b0, MagNarrow_out1};
  assign SpectrumSum_add_cast_1 = {10'b0, {SpectrumGate_out1, 2'b00}};
  assign SpectrumSum_add_temp = SpectrumSum_add_cast + SpectrumSum_add_cast_1;
  assign SpectrumSum_out1 = (SpectrumSum_add_temp[31:22] != 10'b0000000000 ? 20'b11111111111111111111 :
