  lora_fft_Confidence u_Confidence (.clk(clk),
                                    .reset(reset),
                                    .enb(clk_enable),
                                    .dividend_in(PeakNarrow_out1_1),  // ufix20_E1
                                    .divisor_in(GuardedSum_out1_zp),  // ufix20_E3
                                    .quotient(Confidence_out1)  // ufix20_En19
                                    );

  assign confidence = Confidence_out1;

  always @(posedge clk or posedge reset)
    begin : delayMatch10_process
      if (reset == 1'b1) begin
        for(delayMatch10_t_1 = 32'sd0; delayMatch10_t_1 <= 32'sd42; delayMatch10_t_1 = delayMatch10_t_1 + 32'sd1) begin
