    end

  always @* begin
    SpectrumSum_out1_1 = delayMatch11_reg[42];
    delayMatch11_reg_next[0] = SpectrumSum_out1;

    for(delayMatch11_t_0_0 = 32'sd0; delayMatch11_t_0_0 <= 32'sd41; delayMatch11_t_0_0 = delayMatch11_t_0_0 + 32'sd1) begin
      delayMatch11_reg_next[delayMatch11_t_0_0 + 32'sd1] = delayMatch11_reg[delayMatch11_t_0_0];
    end

