  assign spectrumSum = SpectrumSum_out1_1;

  always @(posedge clk or posedge reset)
    begin : delayMatch12_process
      if (reset == 1'b1) begin
        delayMatch12_reg <= {47{1'b0}};
      end
      else begin
        if (enb) begin
          delayMatch12_reg[0] <= symbolBoundary_1;
          delayMatch12_reg[32'sd46:32'sd1] <= delayMatch12_reg[32'sd45:32'sd0];
        end
      end
    end

  assign symbolBoundary = delayMatch12_reg[46];

  lora_fft_TimestampFifo u_TimestampFifo (.clk(clk),
                                          .reset(reset),
                                          .enb(clk_enable),
                                          .sampleCount(sampleCount),  // ufix64
                                          .symbolBoundary(symbolBoundary_1),
                                          .symbolValid(symbolValid_1),
                                          .resetIn(resetIn),
                                          .symbolSampleCount(symbolSampleCount_1),  // ufix64
                                          .timestampValid(timestampValid_1)
