    delayMatch13_reg_next[0] = symbolSampleCount_1;

    for(delayMatch13_t_0_0 = 32'sd0; delayMatch13_t_0_0 <= 32'sd41; delayMatch13_t_0_0 = delayMatch13_t_0_0 + 32'sd1) begin
      delayMatch13_reg_next[delayMatch13_t_0_0 + 32'sd1] = delayMatch13_reg[delayMatch13_t_0_0];
